import hashlib,json,pathlib
base=pathlib.Path(__file__).resolve().parent; root=base.parents[1]
groups={
'tests/conftest.py':[(1,6,'يستورد NumPy وpandas وpytest ودالتي السمات والنوافذ لتجهيز اختبارات، لا بيانات بحثية.'),(9,14,'fixture ‏analytic_prices ينشئ 330 تاريخ عمل وسعرًا تحليلياً 100+0.1t+sin(t)، وOHLC وحجماً صناعياً؛ يعيد DataFrame للاختبارات فقط.'),(17,19,'fixture ‏window_fixture يحول الأسعار الصناعية إلى سمات يومية ونوافذ 30 رصداً ويعيدها للاختبارات التابعة.')],
'tests/test_dashboard.py':[(1,4,'Path وshutil قياسيتان وAppTest أداة اختبار Streamlit.'),(7,15,'ينشئ مشروعاً مؤقتاً مع نسخة الواجهة دون آثار، ويشغلها ويؤكد عدم الاستثناء وظهور رسالة غياب التشغيل وأمر التدريب؛ لا يتحقق من التبويبات عند وجود بيانات.')],
'tests/test_explain_consistency.py':[(1,6,'يستورد أدوات NumPy وpytest ودوال التفسير وملاءمة النماذج.'),(9,19,'اختبار معلم لثلاثة نماذج جدولية: يلائم نموذجاً صغيراً على fixture ويحسب تفسير SHAP لعينتين بخلفية تدريبية، ثم يتحقق من الجمع وثبات التوقع وخطأ إعادة البناء أقل من 0.01؛ لا يثبت سببية التفسير.'),(22,30,'يلائم GradientBoosting صغيراً ويشرح عينة بـ100 اضطراب، ويتحقق من عدم تغيير التنبؤ ومن أن الخطأ هو القيمة المطلقة للفرق بين النموذج والبديل وأن R² الجوار منتهٍ؛ لا يشترط جودة البديل.')],
'tests/test_lstm_training.py':[(1,6,'يستورد أدوات الاختبار وTorch ومكونات LSTM والبذرة.'),(9,17,'يُتخطى اختبار CUDA عند عدم توفره؛ ينشئ شبكة ومدخلات صناعية ويفحص أن قياس الدفعة يسمح بـ cuDNN backward وإنتاجية موجبة وتدرجات منتهية.'),(20,28,'يدرب نموذج CPU صغيراً لحد epochين في مجلد مؤقت، ويحمل checkpoint ويقارن تنبؤ ثلاث نوافذ ويتحقق من النتائج المنتهية والجهاز. هذا اختبار اصطناعي لا تدريب البحث المحفوظ.')],
'tests/test_metrics_and_models.py':[(1,8,'joblib وNumPy وpytest خارجية ودوال المقاييس والحالات والمرجع والمرشحين من المشروع.'),(11,17,'يتحقق من مقاييس يدوية للقيمتين [2,4] والتنبؤ [1,5]: MAE وRMSE يساويان 1 وMAPE 37.5% وR² صفر والدقة الاتجاهية صفر.'),(20,24,'يتحقق أن MAPE غير معرف عند كل أهداف صفرية، وأن العدد المستبعد 2 وR² غير معرف لهدف ثابت.'),(27,29,'يؤكد أن Persistence يعيد الإغلاق الحالي كما هو دون قراءة الهدف المستقبلي.'),(32,38,'يلائم غابة صناعية ويتحقق من تطابق التنبؤ بتكراره عشرين مرة؛ فحص تكرار محلي لا ضمان عبر كل الأجهزة.'),(41,42,'يفحص bull وbear عند تجاوز ±0.05 وsideways عند المساواة أو الصفر.'),(45,54,'اختبار معلم لثلاثة نماذج يلائم ويحفظ مؤقتاً ويعيد تحميل joblib ويقارن التنبؤ ويتحقق من RMSE تحقق غير سالب.')],
'tests/test_provider_integration.py':[(1,8,'يستورد أدوات بناء البيانات والنماذج وSHAP وتحميل اللقطة للتحقق التكاملي.'),(11,22,'اختبار integration يحمل لقطة AAPL المحلية، ويبني النوافذ ويلائم OLS على التدريب، ويختار 10 اختبارات و8 خلفيات ويفحص إعادة بناء SHAP بأقل من 1e-3. يتطلب لقطة محفوظة ويدرّب نموذج اختبار؛ لا يثبت إعادة إنتاج الرسالة.')],
'tests/test_scientific_validation.py':[(1,8,'يستورد replace وNumPy وpytest ودوال المعايير وتصميم التحقق والاتجاه.'),(11,19,'لكل هدف تغير أو عائد يختبر التحويل والتقييس والعكس إلى السعر التالي، وأن x مشترك وy الجديد لا يشارك الذاكرة.'),(22,28,'يضع سعراً سالباً صناعياً ويتوقع رفض العائد، مع إمكان إعادة تركيب السعر من التغير.'),(31,38,'يتحقق من تغطية طيات الاختبار المتصلة دون تداخل وتوافر تسميات التدريب والتحقق وزيادة طول التدريب مع الطيات؛ لا يختبر أزمنة نشر البيانات.'),(41,52,'يغير أهداف الاختبار ويقارن المراجع الثلاثة الثابتة والهدف السابق لأول عينة؛ يثبت أن LastObserved لكل أصل يستخدم الهدف السابق، الذي قد يكون هدف اختبار سابقاً أصبح معروفاً.'),(55,60,'يتحقق من دقة الإشارة ثلاثية الحالات 1/3 عندما يتنبأ الصفر للثلاثة، وتغطية صفر ودقة نشطة غير معرفة ودقة ثنائية 2/3.')],
'tests/test_temporal_integrity.py':[(1,9,'يستورد مكتبات الاختبار ودوال السمات والتقييس والتقسيم والتحقق وبناء النوافذ.'),(12,20,'يغير الأسعار بعد حد زمني لعينة يومية وشهرية ويتحقق من ثبات السمات السابقة؛ لا يثبت سلامة الإصدارات التاريخية للمزود.'),(23,31,'يتحقق أن الهدف هو الإغلاق المعدل للرصد الخام التالي وأن نهاية كل نافذة عند الأصل، وأن أول نافذة تتطابق مع أول ثلاثين صف سمة.'),(34,42,'يتحقق من حجم التدريب والتحقق ومجموع الأقسام وترتيب تواريخ الأهداف وإتاحة التسمية السابقة عند أصل القسم التالي.'),(45,53,'يضرب نوافذ وأهداف التحقق والاختبار في 1000 ثم يعيد ملاءمة المعايير، ويتأكد من ثبات متوسطَي التدريب وسبق آخر هدف تدريب؛ يعدل fixture مؤقتاً.'),(56,59,'يتحقق من أن معيار الهدف وعكسه يسترجعان الوحدات الأصلية ضمن rtol محدد.'),(62,73,'يحقن تكرار تاريخ أو ترتيباً معكوساً أو high خاطئاً أو NaN ويتوقع ValueError من تحقق الأسعار.'),(76,78,'يتوقع رفض تقسيم خمس عينات بدلاً من إنتاج اختبار فارغ.')]
}
manifest={}
for path,entries in groups.items():
 raw=(root/path).read_bytes(); src=raw.decode('utf8').splitlines(); name=path.replace('/','_')+'.md'; digest=hashlib.sha256(raw).hexdigest(); out=['# شرح `'+path+'`','',f'بصمة المصدر SHA-256: `{digest}`.','','وصف الاختبارات لا يعني أنها شُغلت في جلسة التوثيق.','']
 for start,end,desc in entries: out += [f'## الأسطر {start}–{end}','','```python',*src[start-1:end],'```','',desc,'']
 (base/'line_by_line'/name).write_text('\n'.join(out),encoding='utf8')
 manifest[path]={'document':'line_by_line/'+name,'ranges':[[a,b] for a,b,_ in entries],'sha256':digest,'review':'مراجعة يدوية غير مستقلة','quote_verification':'آلي'}
(base/'tests_batch_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf8')
